    def set_descriptor(self, descriptor):
        """
        Sets the function descriptor (a short string used to identify an individual object).

        @param[in] descriptor The descriptor string. Pass @c None to remove the descriptor.
        """

        try:
            if (descriptor is not None):
                if not isinstance(descriptor, (str)):
                    raise TypeError("descriptor must be a string or None.")
                if (sys.version_info.major >= 3):
                    descriptor_char_p = ctypes.c_char_p(descriptor.encode('utf-8'))
                else:
                    descriptor_char_p = ctypes.c_char_p(descriptor)
            else:
                descriptor_char_p = ctypes.c_char_p("")
        except Exception as e:
            raise e
        result = mocaxpy.MocaxCInterface.mocax_set_descriptor(self.__mocax_function,
                                                              descriptor_char_p)
        if result != mocaxpy.MocaxCInterface.MOCAX_I_SUCCESS:
            raise MocaxException(result)

    def get_descriptor(self):
        """
        Gets the function descriptor.

        @return The descriptor of this function.
                Return type: @c str
        """

        descriptor = ctypes.c_char_p()
        length = ctypes.c_int64(0)
        result = mocaxpy.MocaxCInterface.mocax_get_descriptor(self.__mocax_function,
                                                              ctypes.pointer(descriptor),
                                                              ctypes.pointer(length))
        if result != mocaxpy.MocaxCInterface.MOCAX_I_SUCCESS:
            raise MocaxException(result)

        if (descriptor.value is not None):
            if (sys.version_info.major >= 3):
                out_descriptor = str(descriptor.value.decode())
            else:
                out_descriptor = str(descriptor.value)
        else:
            out_descriptor = "";
        return out_descriptor;

    def slice(self, slicing_hyperplane):
        """
        Gets a slice of this function.
        @param slicing_hyperplane A set of pairs, each with the dimension to remove and the point at which will be sliced.
        @return A sliced copy of the function.
                Return type: @c mocaxpy.Mocax.Mocax

        @code
        # See the constructor documentation for an example on how mocax_function may have been created.
        slicing_hyperplane = ((0, 0.5))
        sliced_mocax_function = mocax_function.slice(slicing_hyperplane)
        # Domain of sliced_mocax_function is now one dimension smaller
        @endcode
        """
        hyperplane = copy.deepcopy(slicing_hyperplane)

        # Arguments validation
        if not isinstance(hyperplane, (list, tuple)):
            raise TypeError("slicing_hyperplane has to be a list or a tuple")
        if len(hyperplane) == 2 and isinstance(hyperplane[0], (int, long)) and isinstance(hyperplane[1], (int, long, float)):
            hyperplane = []
            hyperplane.append((slicing_hyperplane[0], slicing_hyperplane[1]))
        for i in xrange(len(hyperplane)):
            if not isinstance(hyperplane[i], (list, tuple)):
                raise TypeError("slicing_hyperplane[" + str(i) + "] has to be a list or a tuple")
            if len(hyperplane[i]) != 2:
                raise TypeError("slicing_hyperplane[" + str(i) + "] must have exactly two elements")
            if not isinstance(hyperplane[i][0], (int, long)):
                raise TypeError("slicing_hyperplane[" + str(i) + "][0] must have an integer number")
            if not isinstance(hyperplane[i][1], (int, long, float)):
                raise TypeError("slicing_hyperplane[" + str(i) + "][1] must have a number")

        # Construction
        num_dimensions_to_remove = len(hyperplane)
        indexes = []
        positions = []
        for i in xrange(len(hyperplane)):
            indexes.append(int(hyperplane[i][0]))
            positions.append(float(hyperplane[i][1]))
        indexes_arr = ((ctypes.c_int64 * num_dimensions_to_remove)(*indexes))
        positions_arr = ((ctypes.c_double * num_dimensions_to_remove)(*positions))
        mocax_sliced = mocaxpy.MocaxCInterface.mocax_allocate()
        result = mocaxpy.MocaxCInterface.mocax_slice_function(self.__mocax_function, num_dimensions_to_remove, indexes_arr, positions_arr, mocax_sliced)
        if result != mocaxpy.MocaxCInterface.MOCAX_I_SUCCESS:
            raise MocaxException(result)
        sliced = Mocax.__new__(Mocax)  # Necessary to instantiate a new Mocax
                                        # (__new__) without calling its constructor/initializator (__init__)
        sliced.__mocax_function = mocax_sliced
        return sliced

    def extrude(self, extrusion_params):
        """
        Expands this function.
        @param extrusion_params A set of pairs, each with the index of the dimension to extrude and the domain of such dimension.
        @return A extruded copy of the function.
                Return type: @c mocaxpy.Mocax.mocax

        @code
        # See the constructor documentation for an example on how mocax_function may have been created.
        extrusion_params = (0, (-1.0, 1.0))
        extruded_mocax_function = mocax_function.extrude(extrusion_params)
        # Domain of extruded_mocax_function is now [(-1, 1), ... ]
        @endcode
        """
        extrusion_parameters = copy.deepcopy(extrusion_params)

        # Arguments validation
        if not isinstance(extrusion_parameters, (list, tuple)):
            raise TypeError("extrusion_parameters has to be a list or a tuple")
        if len(extrusion_parameters) == 2 and isinstance(extrusion_parameters[0], (int, long)) and isinstance(extrusion_parameters[1], (list, tuple)):
            extrusion_parameters = []
            extrusion_parameters.append([extrusion_params[0], (extrusion_params[1][0], extrusion_params[1][1])])
        for i in xrange(len(extrusion_parameters)):
            if not isinstance(extrusion_parameters[i], (list, tuple)):
                raise TypeError("extrusion_params[" + str(i) + "] has to be a list or a tuple")
            if len(extrusion_parameters[i]) != 2:
                raise TypeError("extrusion_params[" + str(i) + "] must have exactly two elements")
            if not isinstance(extrusion_parameters[i][0], (int, long)):
                raise TypeError("extrusion_params[" + str(i) + "][0] must have an integer number")
            if not isinstance(extrusion_parameters[i][1], (list, tuple)):
                raise TypeError("extrusion_params[" + str(i) + "][1] has to be a list or a tuple")
            if len(extrusion_parameters[i][1]) != 2:
                raise TypeError("extrusion_params[" + str(i) + "][1] has to contain two elements")
            if not isinstance(extrusion_parameters[i][1][0], (int, long, float)):
                raise TypeError("extrusion_params[" + str(i) + "][1][0] must have a number")
            if not isinstance(extrusion_parameters[i][1][1], (int, long, float)):
                raise TypeError("extrusion_params[" + str(i) + "][1][1] must have a number")

        # Construction
        num_dimensions_to_add = len(extrusion_parameters)
        indexes = []
        domains = []
        for i in xrange(num_dimensions_to_add):
            indexes.append(int(extrusion_parameters[i][0]))
            domains.append([float(extrusion_parameters[i][1][0]), float(extrusion_parameters[i][1][1])])
        indexes_arr = ((ctypes.c_int64 * num_dimensions_to_add)(*indexes))
        mocax_domains = mocaxpy.MocaxDomain(domains)
        domains_arr = mocax_domains.export_as_multidimensional_array()
        mocax_extruded = mocaxpy.MocaxCInterface.mocax_allocate()
        result = mocaxpy.MocaxCInterface.mocax_extrude_function(self.__mocax_function, num_dimensions_to_add, indexes_arr, domains_arr, mocax_extruded)
        if result != mocaxpy.MocaxCInterface.MOCAX_I_SUCCESS:
            raise MocaxException(result)
        extruded = Mocax.__new__(Mocax) # Necessary to instantiate a new Mocax
                                        # (__new__) without calling its constructor/initializator (__init__)
        extruded.__mocax_function = mocax_extruded
        return extruded


    def __str__(self):
        """
        Gets a string representation/summary of this function.
        @return The function summary in string format.
                Return type: @c str
        """
        description = ctypes.c_char_p()
        length = ctypes.c_int64(0)
        result = mocaxpy.MocaxCInterface.mocax_function_to_string(self.__mocax_function,
                                                                  ctypes.pointer(description),
                                                                  ctypes.pointer(length))
        if result != mocaxpy.MocaxCInterface.MOCAX_I_SUCCESS:
            raise MocaxException(result)

        if (sys.version_info.major >= 3):
            out_description = str(description.value.decode())
        else:
            out_description = str(description.value)
        return out_description

    def __iadd__(self, other):
        """
        Assignment with increment operator.

        "Increments" a Mocax object by adding another.
        @param[in] other The second Mocax object ("the increment") that will be added to this one. Allowed types: mocaxpy.Mocax.Mocax
        @return A reference to self.
                Return type: mocaxpy.Mocax.Mocax
        """

        if not isinstance(other, mocaxpy.Mocax):
            raise NotImplementedError()
        new_mocax_function = mocaxpy.MocaxCInterface.mocax_allocate()
        result = mocaxpy.MocaxCInterface.mocax_add_functions(self.__mocax_function,
                                                               other._Mocax__mocax_function, new_mocax_function)
        if result != mocaxpy.MocaxCInterface.MOCAX_I_SUCCESS:
            raise MocaxException(result)
        mocaxpy.MocaxCInterface.mocax_destroy(self.__mocax_function)
        self.__mocax_function = new_mocax_function
        return self

    def __isub__(self, other):
        """
        Assignment with decrement operator.

        "Decrements" a Mocax object by subtracting another.
        @param[in] other The second Mocax object ("the decrement") that will be subtracted from this one. Allowed types: mocaxpy.Mocax.Mocax
        @return A reference to self.
                Return type: mocaxpy.Mocax.Mocax
        """

        if not isinstance(other, mocaxpy.Mocax):
            raise NotImplementedError()
        new_mocax_function = mocaxpy.MocaxCInterface.mocax_allocate()
        result = mocaxpy.MocaxCInterface.mocax_subtract_functions(self.__mocax_function,
                                                                    other._Mocax__mocax_function, new_mocax_function)
        if result != mocaxpy.MocaxCInterface.MOCAX_I_SUCCESS:
            raise MocaxException(result)
        mocaxpy.MocaxCInterface.mocax_destroy(self.__mocax_function)
        self.__mocax_function = new_mocax_function
        return self

    def __imul__(self, rhs):
        """
        Assignment with scaling operator.

        Scales a Mocax object by a given factor.
        @param[in] rhs The scale operator. Allowed types: int, long, float
        @return A reference to self.
                Return type: mocaxpy.Mocax.Mocax
        """

        try:
            if not isinstance(rhs, (int, long, float, str)):
                raise TypeError()
            rhs = float(rhs)
        except:
            raise TypeError("rhs must be a real number or a string parseable to a real")
        new_mocax_function = mocaxpy.MocaxCInterface.mocax_allocate()
        result = mocaxpy.MocaxCInterface.mocax_scale_function(self.__mocax_function,
                                                              rhs,
                                                              new_mocax_function)
        if result != mocaxpy.MocaxCInterface.MOCAX_I_SUCCESS:
            raise MocaxException(result)
        mocaxpy.MocaxCInterface.mocax_destroy(self.__mocax_function)
        self.__mocax_function = new_mocax_function
        return self

    def __add__(self, other):
        """
        Addition operator.

        Adds two Mocax objects.
        @param[in] other A second Mocax object that will be added to this one. Allowed types: mocaxpy.Mocax.Mocax
        @return A new Mocax resulting from the addition of this Mocax and another.
                Return type: mocaxpy.Mocax.Mocax
        """

        if not isinstance(other, mocaxpy.Mocax):
            raise NotImplementedError()
        out_mocax = self.clone()
        out_mocax += other
        return out_mocax

    def __sub__(self, other):
        """
        Subtraction operator.

        Subtracts two Mocax objects.
        @param[in] other A second Mocax object that will be subtracted from this one. Allowed types: mocaxpy.Mocax.Mocax
        @return A new Mocax resulting from the subtraction of a Mocax from this one.
                Return type: mocaxpy.Mocax.Mocax
        """

        if not isinstance(other, mocaxpy.Mocax):
            raise NotImplementedError()
        out_mocax = self.clone()
        out_mocax -= other
        return out_mocax

    def __mul__(self, rhs):
        """
        Scaling operator.

        Scales a Mocax object by a given factor.
        @param[in] rhs The scaling factor. Allowed types: int, long, float
        @return A new Mocax equivalent to the scaled given Mocax object.
                Return type: mocaxpy.Mocax.Mocax
        """

        try:
            if not isinstance(rhs, (int, long, float, str)):
                raise TypeError()
            rhs = float(rhs)
        except:
            raise TypeError("rhs must be a real number or a string parseable to a real")
        out_mocax = self.clone()
        out_mocax *= rhs
        return out_mocax

    __rmul__ = __mul__

    def __init(self):
        self.__mocax_function = mocaxpy.MocaxCInterface.mocax_allocate()
